window.OwaysAPI={async request(url,data){const response=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=await response.json()}catch{throw Error('هذه الصفحة تحتاج تشغيل خادم المشروع عبر npm start، وليس Live Server.')}if(!response.ok)throw Error(result.error||'تعذر إتمام الطلب.');return result},escape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}};
